import {mul,translate} from './core.js';
export const unitScale={px:1,mm:96/25.4,cm:96/2.54,in:96};
export const convertUnits=(value,from,to)=>value*unitScale[from]/unitScale[to];
export const documentPresets={square:[1000,1000,'px'],a4:[210,297,'mm'],a4landscape:[297,210,'mm'],a3:[297,420,'mm'],social:[1080,1080,'px'],portrait:[1080,1350,'px']};
export function documentSpec({width=1000,height=1000,unit='px',ppi=300,background='white',color='#ffffff'}={}){if(!unitScale[unit]||![width,height,ppi].every(v=>Number.isFinite(Number(v))&&Number(v)>0)||width*unitScale[unit]>20000||height*unitScale[unit]>20000||ppi>2400)throw Error('Ingresá dimensiones positivas hasta 20000 px y resolución hasta 2400 ppp.');if(!['white','transparent','custom'].includes(background))background='white';if(!/^#[\da-f]{6}$/i.test(color))color='#ffffff';return {width:Number(width),height:Number(height),unit,ppi:Number(ppi),background,color,widthPx:width*unitScale[unit],heightPx:height*unitScale[unit]};}
export function migrateDocument(p){p.document??=documentSpec({width:700,height:700,ppi:96});p.document=documentSpec(p.document);const defaults={fill:'#1f2428',stroke:'#292e2c',opacity:1,target:'fill',applyTo:'this',recent:[],swatches:['#1f2428','#f1ede3','#334b3d','#26334f','#c84040']};p.colors={...defaults,...p.colors};const valid=v=>v==='none'||/^#[\da-f]{6}$/i.test(v);for(const key of ['fill','stroke'])if(!valid(p.colors[key]))p.colors[key]=defaults[key];for(const key of ['recent','swatches'])p.colors[key]=Array.isArray(p.colors[key])?p.colors[key].filter(valid).slice(0,key==='recent'?12:64):defaults[key];p.colors.opacity=Number.isFinite(p.colors.opacity)?Math.max(0,Math.min(1,p.colors.opacity)):1;p.colors.target=p.colors.target==='stroke'?'stroke':'fill';p.colors.applyTo=p.colors.applyTo==='both'?'both':'this';return p;}
export function configureDocument(p,spec){p.document=documentSpec(spec);const d=p.document,s=Math.min(d.widthPx,d.heightPx)/700,m=mul(translate((d.widthPx-700*s)/2,(d.heightPx-700*s)/2),[s,0,0,s,0,0]);for(const os of Object.values(p.views))for(const o of os)if(!o.source){o.matrix=mul(m,o.matrix);if(o.collapseBackup)o.collapseBackup=mul(m,o.collapseBackup);if(o.symmetry)o.symmetry.axis=d.widthPx/2;}p.centerAxis=d.widthPx/2;delete p.garment.shared;p.garment.attachments=[];p.garment.dimensions={};return migrateDocument(p);}
export function rasterSize(p,scale=1){const d=p.document||documentSpec({width:700,height:700,ppi:96}),factor=d.unit==='px'?1:d.ppi/96;return {width:Math.max(1,Math.round(d.widthPx*factor*scale)),height:Math.max(1,Math.round(d.heightPx*factor*scale)),ppi:d.ppi*scale};}
export const documentBackground=p=>p.document?.background==='transparent'?'none':p.document?.background==='custom'?p.document.color:'#ffffff';
// Canvas encoders omit physical resolution. Insert a standard PNG pHYs chunk.
export function pngResolution(bytes,ppi){const input=new Uint8Array(bytes),data=new Uint8Array(9),dv=new DataView(data.buffer);dv.setUint32(0,Math.round(ppi/0.0254));dv.setUint32(4,Math.round(ppi/0.0254));data[8]=1;const type=new TextEncoder().encode('pHYs'),payload=new Uint8Array(13);payload.set(type);payload.set(data,4);let crc=0xffffffff;for(const b of payload){crc^=b;for(let i=0;i<8;i++)crc=crc&1?(crc>>>1)^0xedb88320:crc>>>1;}const chunk=new Uint8Array(21),cv=new DataView(chunk.buffer);cv.setUint32(0,9);chunk.set(payload,4);cv.setUint32(17,(crc^0xffffffff)>>>0);let offset=8,parts=[input.slice(0,8)];while(offset+12<=input.length){const len=new DataView(input.buffer,input.byteOffset+offset,4).getUint32(0),name=new TextDecoder().decode(input.slice(offset+4,offset+8));if(name!=='pHYs')parts.push(input.slice(offset,offset+len+12));if(name==='IHDR')parts.push(chunk);offset+=len+12;}const out=new Uint8Array(parts.reduce((n,p)=>n+p.length,0));offset=0;for(const p of parts){out.set(p,offset);offset+=p.length;}return out;}
